/// The grammar of the toy language.
///
/// The LALR table for this grammar is generated by `build.rs` into
/// `$OUT_DIR/lalr_table.rs`, so the compiler does not build it at startup.
pub const GRAMMAR: &str = include_str!("../../spec/toy.lang.grammar");

#[cfg(test)]
mod tests {
    use super::GRAMMAR;
    use toycomp_syntax::Grammar;

    #[test]
    fn grammar_parses() {
        let parsed_grammar = Grammar::from_str(GRAMMAR);
        assert!(parsed_grammar.is_ok());
    }
}
